<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Track Trip · {{ $company?->name }}</title><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><style>
*{box-sizing:border-box}body{margin:0;background:#f3f6fb;color:#172033;font-family:Arial,sans-serif}.shell{max-width:820px;margin:auto;padding:18px}.brand{display:flex;align-items:center;gap:12px;margin:8px 0 20px}.brand img{max-width:54px;max-height:54px}.brand strong{font-size:22px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.card{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:18px;margin-bottom:14px}.label{color:#64748b;font-size:11px;text-transform:uppercase;letter-spacing:.8px}.status{text-transform:capitalize;font-size:22px;font-weight:700;margin-top:5px}#map{height:390px;border-radius:14px;background:#e2e8f0}.photo-button{float:left;margin:0 12px 8px 0;padding:0;border:0;border-radius:50%;background:transparent;cursor:zoom-in}.photo{display:block;width:64px;height:64px;border-radius:50%;object-fit:cover}.meta{color:#475569;line-height:1.6}.stale{color:#b45309}.photo-modal{position:fixed;inset:0;z-index:1000;display:flex;align-items:center;justify-content:center;padding:24px;background:rgba(15,23,42,.78)}.photo-modal[hidden]{display:none}.photo-modal img{max-width:min(92vw,620px);max-height:80vh;border-radius:16px;box-shadow:0 22px 60px rgba(0,0,0,.45)}.photo-close{position:absolute;top:18px;right:18px;width:40px;height:40px;border:0;border-radius:50%;background:#fff;color:#172033;font-size:25px;line-height:1;cursor:pointer}@media(max-width:620px){.grid{grid-template-columns:1fr}#map{height:330px}}
</style></head><body><main class="shell"><div class="brand">@if($company?->logo)<img src="{{ $company->logo }}" alt="Logo">@endif <strong>{{ $company?->name ?? config('app.name') }}</strong></div><div class="grid"><section class="card"><div class="label">Booking #{{ $booking->id }}</div><div id="status" class="status">{{ str_replace('_',' ',$booking->status) }}</div><div id="updated" class="meta">Waiting for location…</div></section><section class="card" id="details"><div class="label">Driver and vehicle</div></section></div><div id="map"></div></main><div id="photoModal" class="photo-modal" hidden role="dialog" aria-modal="true" aria-label="Driver photo"><button id="photoClose" class="photo-close" type="button" aria-label="Close photo">×</button><img id="photoLarge" src="" alt="Driver"></div><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script src="https://cdn.jsdelivr.net/npm/pusher-js@8.4.0/dist/web/pusher.min.js"></script><script>
const token=@json($token),channelKey=@json($channelKey),reverbKey=@json($reverbKey),api='/api/public/trip-tracking/'+encodeURIComponent(token);let map=null,marker=null;
function showLocation(location){if(!location)return;const point=[Number(location.latitude),Number(location.longitude)];if(!map){map=L.map('map').setView(point,15);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(map);marker=L.marker(point).addTo(map)}else{marker.setLatLng(point);map.panTo(point)}const updated=location.recorded_at?new Date(location.recorded_at):new Date();const stale=Date.now()-updated.getTime()>120000;document.getElementById('updated').className='meta'+(stale?' stale':'');document.getElementById('updated').textContent=(stale?'Last known location · ':'Location updated · ')+updated.toLocaleTimeString()}
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[character]))}
function openDriverPhoto(url){if(!url)return;document.getElementById('photoLarge').src=url;document.getElementById('photoModal').hidden=false}function closeDriverPhoto(){document.getElementById('photoModal').hidden=true;document.getElementById('photoLarge').src=''}document.getElementById('photoClose').addEventListener('click',closeDriverPhoto);document.getElementById('photoModal').addEventListener('click',event=>{if(event.target===event.currentTarget)closeDriverPhoto()});document.addEventListener('keydown',event=>{if(event.key==='Escape')closeDriverPhoto()});
function render(data){document.getElementById('status').textContent=String(data.status||'').replaceAll('_',' ');const d=data.driver||{},v=data.vehicle||{},details=document.getElementById('details');details.innerHTML='<div class="label">Driver and vehicle</div>'+(d.photo?'<button class="photo-button" type="button" aria-label="View driver photo"><img class="photo" src="'+escapeHtml(d.photo)+'" alt="Driver"></button>':'')+'<div class="meta"><strong>'+escapeHtml(d.name||'Driver assigned')+'</strong><br>'+escapeHtml(d.phone||'')+'<br><strong>'+escapeHtml(v.name||'Vehicle pending')+'</strong><br>'+escapeHtml([v.color,v.model,v.plate_number].filter(Boolean).join(' · '))+'</div><div style="clear:both"></div>';details.querySelector('.photo-button')?.addEventListener('click',()=>openDriverPhoto(d.photo));showLocation(data.location)}
async function load(){const response=await fetch(api,{headers:{Accept:'application/json'}});if(response.ok)render((await response.json()).data)}load();setInterval(load,10000);
try{const pusher=new Pusher(reverbKey,{wsHost:location.hostname,wsPort:location.port||80,wssPort:location.port||443,wsPath:'/ws',forceTLS:location.protocol==='https:',enabledTransports:['ws','wss'],disableStats:true,cluster:'mt1'});pusher.subscribe('trip.'+channelKey).bind('booking.location.updated',event=>showLocation(event.location||event))}catch(error){}
</script></body></html>
